import json
import numpy as np
from collections import defaultdict
import matplotlib.pyplot as plt

def task_func(input_file):
    def is_numeric(value):
        return isinstance(value, (int, float, np.integer, np.floating)) and not isinstance(
            value, (bool, np.bool_)
        )

    with open(input_file, "r", encoding="utf-8") as f:
        data = json.load(f)

    if not isinstance(data, list):
        raise TypeError("Input JSON must be a list of dictionaries.")

    values_by_key = defaultdict(list)
    key_order = []

    for item in data:
        if not isinstance(item, dict):
            raise TypeError("Each item in the input JSON list must be a dictionary.")
        for key, value in item.items():
            if key not in values_by_key:
                key_order.append(key)
            if is_numeric(value):
                values_by_key[key].append(value)

    result = {}
    plots = []

    for key in key_order:
        values = values_by_key.get(key, [])
        if values:
            arr = np.array(values, dtype=float)
            mean_val = float(np.mean(arr))
            median_val = float(np.median(arr))
        else:
            mean_val = np.nan
            median_val = np.nan

        result[key] = {"mean": mean_val, "median": median_val}

        fig, ax = plt.subplots()
        stats_names = ["mean", "median"]
        stats_values = [mean_val, median_val]
        ax.bar(stats_names, stats_values)
        ax.set_title(f"Statistics for {key}")
        ax.set_ylabel("Value")
        plots.append(ax)

    return result, plots
